// Package stdtypes holds the type information of the standard library (gc
// export data generated by cmd/stdexport for the platform), so that plugins
// can be type-checked without a Go toolchain: the VM calls the standard
// library natively and only needs its types.
package stdtypes

//go:generate go run ../cmd/stdexport -out .

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	pathpkg "path"
	"runtime"
	"slices"
	"sort"
	"strconv"
	"strings"
	"sync"

	"golang.org/x/tools/go/gcexportdata"

	"github.com/traefik/yaegi/v2/internal/gorelease"
)

// Universe is the set of standard library packages, all imported once:
// after Load returns, the packages never change, so they can be shared by
// plugins type-checked concurrently.
type Universe struct {
	Fset      *token.FileSet
	GoVersion string // major.minor the data was generated with ("go1.26")
	pkgs      map[string]*types.Package
	paths     []string
	src       map[string]*SourcePackage
	inits     map[string][]string // see InitTask
}

// SourcePackage is a standard library package type-checked from its embedded
// sources: cmp, iter, slices and maps, whose generic functions have no native
// instantiation (the VM interprets their instances), and container/list and
// container/ring, which the VM interprets.
type SourcePackage struct {
	Files []*ast.File
	Info  *types.Info
}

var (
	once   sync.Once
	shared *Universe
	err    error
)

// Platforms are the GOOS/GOARCH pairs with embedded data (cmd/stdexport),
// the targets of the Traefik releases. The host can check at build time
// that its target is in the list. Elsewhere vm.Load refuses to load a
// plugin, unless the host asks for go list (vm.Options.GoList). They are
// also the platforms with a syscall table in package stdsyms (cmd/stdsyms):
// the API of syscall is different on each platform. The list is in package
// internal/gorelease, which the generators share: when you change it, run
// go generate ./stdtypes ./stdsyms.
var Platforms = gorelease.Platforms

// Available reports whether data is embedded for this platform.
func Available() bool { return len(data) > 0 }

// Load returns the process-wide universe, decoding the embedded data on the
// first call. It fails when no data is embedded for this platform or when the
// data was generated with another Go release than the running binary, whose
// native standard library would not match it. The second case should not
// happen: the data files are only built by the release they were generated
// with, and the guard file stops the build on any other release.
func Load() (*Universe, error) {
	once.Do(func() { shared, err = decode(data) })
	return shared, err
}

func decode(data []byte) (*Universe, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("stdtypes: no data for %s/%s", runtime.GOOS, runtime.GOARCH)
	}
	zr, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	r := bufio.NewReader(zr)
	header := make([]string, 3)
	for i := range header {
		l, err := r.ReadString('\n')
		if err != nil {
			return nil, fmt.Errorf("stdtypes: header: %v", err)
		}
		header[i] = strings.TrimSuffix(l, "\n")
	}
	if header[0] != "govm-stdtypes 3" {
		return nil, fmt.Errorf("stdtypes: unknown format %q", header[0])
	}
	if want := runtime.GOOS + "/" + runtime.GOARCH; header[2] != want {
		return nil, fmt.Errorf("stdtypes: data for %s, running on %s", header[2], want)
	}
	if v := Release(runtime.Version()); header[1] != v {
		return nil, fmt.Errorf("stdtypes: data generated for %s, binary built with %s: use a yaegi v2 version made for %s (in a yaegi v2 checkout: go generate ./stdtypes)", header[1], runtime.Version(), v)
	}
	entries := map[string][]byte{}
	var paths []string
	srcFiles := map[string]map[string][]byte{} // package -> file name -> source
	var srcOrder []string
	inits := map[string][]string{}
	for {
		l, err := r.ReadString('\n')
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		l = strings.TrimSuffix(l, "\n")
		i := strings.LastIndexByte(l, ' ')
		if i < 0 {
			return nil, fmt.Errorf("stdtypes: bad entry %q", l)
		}
		path := l[:i]
		n, err := strconv.Atoi(l[i+1:])
		if err != nil {
			return nil, fmt.Errorf("stdtypes: bad entry %q", l)
		}
		b := make([]byte, n)
		if _, err := io.ReadFull(r, b); err != nil {
			return nil, err
		}
		if file, ok := strings.CutPrefix(path, "!src "); ok {
			pkg, name := pathpkg.Split(file)
			pkg = strings.TrimSuffix(pkg, "/")
			if srcFiles[pkg] == nil {
				srcFiles[pkg] = map[string][]byte{}
				srcOrder = append(srcOrder, pkg)
			}
			srcFiles[pkg][name] = b
			continue
		}
		if pkg, ok := strings.CutPrefix(path, "!init "); ok {
			inits[pkg] = strings.Fields(string(b))
			continue
		}
		entries[path] = b
		paths = append(paths, path)
	}
	u := &Universe{Fset: token.NewFileSet(), GoVersion: header[1], pkgs: map[string]*types.Package{}, paths: paths,
		src: map[string]*SourcePackage{}, inits: inits}
	read := func(path string) error {
		if p := u.pkgs[path]; p != nil && p.Complete() {
			return nil
		}
		b, ok := entries[path]
		if !ok {
			return fmt.Errorf("stdtypes: no data for %s", path)
		}
		if _, err := gcexportdata.Read(bytes.NewReader(b), u.Fset, u.pkgs, path); err != nil {
			return fmt.Errorf("stdtypes: %s: %v", path, err)
		}
		return nil
	}
	// The source packages first (the generator lists them dependencies
	// first): every export entry read afterwards that refers to their
	// objects reuses them, so there is one package object per path.
	for _, pkg := range srcOrder {
		sp, tp, err := u.checkSource(pkg, srcFiles[pkg], read)
		if err != nil {
			return nil, err
		}
		u.pkgs[pkg] = tp
		u.src[pkg] = sp
	}
	// Each entry also declares the parts of its dependencies it refers to;
	// reading every entry into one map completes all packages.
	for _, path := range paths {
		if err := read(path); err != nil {
			return nil, err
		}
	}
	return u, nil
}

// checkSource type-checks an embedded source package; read loads the export
// data of its imports first.
func (u *Universe) checkSource(path string, files map[string][]byte, read func(string) error) (*SourcePackage, *types.Package, error) {
	names := make([]string, 0, len(files))
	for n := range files {
		names = append(names, n)
	}
	sort.Strings(names)
	sp := &SourcePackage{Info: &types.Info{
		Types: map[ast.Expr]types.TypeAndValue{}, Defs: map[*ast.Ident]types.Object{}, Uses: map[*ast.Ident]types.Object{},
		Implicits: map[ast.Node]types.Object{}, Selections: map[*ast.SelectorExpr]*types.Selection{}, Scopes: map[ast.Node]*types.Scope{},
		Instances: map[*ast.Ident]types.Instance{}, FileVersions: map[*ast.File]string{},
	}}
	for _, n := range names {
		f, err := parser.ParseFile(u.Fset, "$GOROOT/src/"+path+"/"+n, files[n], parser.ParseComments|parser.SkipObjectResolution)
		if err != nil {
			return nil, nil, err
		}
		sp.Files = append(sp.Files, f)
		for _, imp := range f.Imports {
			ip, _ := strconv.Unquote(imp.Path.Value)
			if ip != "unsafe" && u.src[ip] == nil {
				if err := read(ip); err != nil {
					return nil, nil, err
				}
			}
		}
	}
	conf := types.Config{
		GoVersion: u.GoVersion,
		Sizes:     types.SizesFor("gc", runtime.GOARCH),
		Importer:  importerFunc(u.Import),
	}
	tp, err := conf.Check(path, u.Fset, sp.Files, sp.Info)
	if err != nil {
		return nil, nil, fmt.Errorf("stdtypes: %s: %v", path, err)
	}
	return sp, tp, nil
}

type importerFunc func(string) (*types.Package, error)

func (f importerFunc) Import(path string) (*types.Package, error) { return f(path) }

// Source returns the files and type information of a package type-checked
// from embedded sources, or nil.
func (u *Universe) Source(path string) *SourcePackage { return u.src[path] }

// InitTask reports whether the standard library package path has an init
// task in gc, and returns the packages of its imports that have one. The
// compiler writes an init task for a package that has init work (init
// functions, variables that are not static data) or that imports a package
// with an init task; the linker orders the init of a program over the graph
// of the tasks (cmd/link/internal/ld/inittask.go). A package without a task,
// as unicode/utf8, is not in the graph: the packages that import it do not
// wait for it. cmd/stdexport reads the graph from the object files.
func (u *Universe) InitTask(path string) (deps []string, ok bool) {
	deps, ok = u.inits[path]
	return deps, ok
}

// Has reports whether path is a standard library package.
func (u *Universe) Has(path string) bool {
	_, ok := u.pkgs[path]
	return ok || path == "unsafe"
}

// IsStd reports whether path is the import path of a standard library
// package of this Go release, on any platform of Platforms. It does not
// decode the data and works on every platform. As for the go command, a
// path without a dot in its first element is not enough: the packages of a
// main module "test" or "repro" (test/a, repro/b) are not standard.
func IsStd(path string) bool {
	_, ok := slices.BinarySearch(stdPaths, path)
	return ok
}

// Import returns the package path.
func (u *Universe) Import(path string) (*types.Package, error) {
	if path == "unsafe" {
		return types.Unsafe, nil
	}
	if p, ok := u.pkgs[path]; ok {
		return p, nil
	}
	return nil, fmt.Errorf("stdtypes: %s is not a standard library package", path)
}

// Packages returns all packages, sorted by path.
func (u *Universe) Packages() []*types.Package {
	ps := make([]*types.Package, 0, len(u.pkgs))
	for _, p := range u.pkgs {
		ps = append(ps, p)
	}
	sort.Slice(ps, func(i, j int) bool { return ps[i].Path() < ps[j].Path() })
	return ps
}

// Release returns the release of a Go version: "go1.26" for "go1.26.8",
// "go1.27rc1" or "go1.27". Other strings (devel builds) come back as is.
func Release(v string) string { return gorelease.Release(v) }
